<?php

namespace App\Tailoring;

?>
<h1 class="h3 mb-4"><?= t('Payments')?></h1><?php if ($admin) { ?><div class="d-flex gap-2 mb-4"><a class="btn btn-outline-primary" href="/admin/payments"><?= t('All payments')?></a><a class="btn btn-outline-primary" href="/admin/payments?status=PENDING"><?= t('Pending payments')?></a></div><?php } ?><div class="card"><div class="card-body"><div class="table-responsive"><table class="table align-middle"><thead><tr><th><?= t('Order')?></th><th><?= t('Amount')?></th><th><?= t('Method')?></th><th><?= t('Status')?></th><th><?= t('Payment reference')?></th><th><?= t('Receipt')?></th><?php if ($admin) { ?><th><?= t('Action')?></th><?php } ?></tr></thead><tbody><?php foreach ($payments as $payment) { ?><tr><td><a href="/<?= $admin ? 'admin' : 'customer'?>/orders/<?= (int) $payment['order_id']?>"><?= e($payment['order_number'])?></a></td><td><?= money($payment['amount'])?></td><td><?= e($payment['method'])?></td><td><span class="badge text-bg-<?= $payment['status'] === 'VERIFIED' ? 'success' : 'warning'?>"><?= e($payment['status'])?></span></td><td><?= e($payment['transaction_reference'] ?: '—')?></td><td><a href="/<?= $admin ? 'admin' : 'customer'?>/payments/<?= (int) $payment['id']?>/receipt" target="_blank" rel="noopener"><?= t('Print receipt')?></a></td><?php if ($admin) { ?><td><?php if ($payment['status'] === 'PENDING') { ?><form action="/admin/payments/<?= (int) $payment['id']?>/verify" method="post"><?= csrf_field()?><label class="small d-block mb-2"><input type="checkbox" required> <?= t('I have checked this payment.')?></label><button class="btn btn-sm btn-primary"><?= t('Verify payment')?></button></form><?php } ?></td><?php } ?></tr><?php } ?><?php if (! $payments) { ?><tr><td colspan="7"><?= t('No payments yet.')?></td></tr><?php } ?></tbody></table></div></div></div>
